import React from 'react';
import '../../styles/homeAdmin.css';
import Logo from '../assets/LeSpotLogo.png';

function HomeAdmin() {
    return (
        <div className="admin-layout">
            
            {/* --- SIDEBAR GAUCHE --- */}
            <aside className="admin-sidebar">
                <div className="admin-brand">
                    <img src={Logo} alt="Logo" className="logo" />
                </div>
                <ul className="admin-menu-list">
                    <li className="admin-menu-item">📊 Dashboard</li>
                    <li className="admin-menu-item">🏄‍♂️ Articles</li>
                    <li className="admin-menu-item">📦 Commandes</li>
                    <li className="admin-menu-item">📅 Services & Cours</li>
                    <li className="admin-menu-item">⚠️ Litiges</li>
                </ul>
            </aside>

            {/* --- ZONE PRINCIPALE (DROITE) --- */}
            <div className="admin-main-area">
                
                {/* HEADER HAUT */}
                <header className="admin-header">
                    <h2>Vue d'ensemble</h2>
                    <div className="admin-user-profile">
                        👋 Bonjour, Hugo
                    </div>
                </header>

                {/* CONTENU CENTRAL */}
                <main className="admin-content-wrapper">
                    <div className="admin-content-card">
                        <h3>Bienvenue dans l'espace de gestion</h3>
                        <p>
                            C'est ici que s'afficheront tes tableaux de données (CRUD) pour ajouter tes planches de surf, valider les commandes ou répondre aux réclamations.
                        </p>
                    </div>
                </main>

            </div>
        </div>
    );
}

export default HomeAdmin;
